"""Unlike other configs, this dictionary is autogenerated by p1_generate_config.py.
However, there is also a read function that is specifically used for the prepared YAML config,
where parameter key is written. This class is created as many downstream analyses require these
variables to store as a unique identities and other tasks.
"""

import logging

from typing import Any
from typing_extensions import Self

from scramblebench.script.config_preparation import config_constant, config_input, \
                                                    config_model, config_generation

logger = logging.getLogger(__name__)

class ParameterConfig:
    """parameter config containing protein name, model name list, num sample, and batch parameters that are
    saved by other classes. This class is built so that there is no need to access various classes multiple times.
    """

    def __init__(self, config_data: dict[str, Any]=None):
        """initialize the class. There are two types of using this. 

        First, user can use ParameterConfig().create().write() to create a parameter dictionary. 
        This can be seen in p1_generate_config.py. 
        
        Second, user can use ParameterConfig(), similar to other class 
        once the parameter dictionary is created.

        Args:
            config_data (dict[str, Any], optional): user's prepared YAML config with 
                                                    'parameter' parameter key as dictionary. Defaults to None.

        Raises:
            KeyError: if parameter key is not available in the prepared YAML config
        """

        self.name = config_constant.PARAMETER_KEY

        self.protein_name = 'protein_name'
        self.model_list_name = 'model_list'
        self.num_sample_name = 'num_sample'
        self.batch_parameter_name = 'batch_parameter'

        self.protein_value = None
        self.model_list_value = []
        self.batch_parameter_dict = {}

        if config_data:

            if self.name not in config_data:
                raise KeyError(f'You forgot to put "{self.name}" key in your config file!')

            parameter_data = config_data[self.name]
            self.protein_value = parameter_data[self.protein_name]
            self.model_list_value = parameter_data[self.model_list_name]
            self.batch_parameter_dict = parameter_data[self.batch_parameter_name]
            self.num_sample_value = parameter_data[self.num_sample_name]


    def create(self, config_data: dict[str, Any], batch_parameter: dict[str, Any]) -> Self:
        """method used to prepare a dictionary once .write() is used. 

        Args:
            config_data (dict[str, Any]): user's input YAML config data as dictionary. This will be read by
            InputConfig, ModelConfig, and GenerationConfig, hence making this method dependent on them. Should a
            user desired to use .create() without these classes, it is best to directly generate the YAML structure
            manually or use .update() one by one

            batch_parameter (dict[str, Any]): batch parameters that have been prepared in p1_generate_config.py.
            This variable will be mostly used in the p6_generate_report.py

        Returns:
            Self: ParameterConfig
        """

        self.name = config_constant.PARAMETER_KEY

        input_data = config_input.InputConfig(input_dict=config_data)
        self.protein_name = input_data.protein_name
        self.protein_value = input_data.protein_value

        self.model_list_value = config_model.ModelConfig(config_data=config_data).get_model_list()
        self.num_sample_value = config_generation.GenerationConfig(config_data=config_data)\
                                                            .parameter_value.num_sample_value

        self.batch_parameter_dict = batch_parameter

        return self


    def update(self, key: str, value: Any) -> Self:
        """update the value of a key. While the type check is not robust, this should be good enough

        Args:
            key (str): valid ParameterConfig key
            value (Any): new value that will be updated

        Raises:
            ValueError: if protein name is not a string
            ValueError: if model list is not a list
            ValueError: if num sample is not an integer
            ValueError: if batch parameter is not a dictionary
            KeyError: invalid ParameterConfig key

        Returns:
            Self: ParameterConfig
        """
        if key == self.protein_name:
            if not isinstance(value, str):
                raise ValueError(f'protein name should be a string, not {type(value)}')
            self.protein_value = value
        elif key == self.model_list_name:
            if not isinstance(value, list):
                raise ValueError(f'model list should be a list, not {type(value)}')
            self.model_list_value = value
        elif key == self.num_sample_name:
            if not isinstance(value, int):
                raise ValueError(f'num sample should be an int, not {type(value)}')
            self.num_sample_value = value
        elif key == self.batch_parameter_name:
            if not isinstance(value, dict):
                raise ValueError(f'batch parameter should be a dictionary, not {type(value)}')
            self.batch_parameter_dict = value
        else:
            raise KeyError(f'There is no key of {key}')

        return self


    def write(self)-> dict[str, dict]:
        """Write the standardised config format for ParameterConfig

        Returns:
            dict[str, dict]: ParameterConfig as dictionary
        """
        return {self.name: {self.protein_name: self.protein_value,
                            self.model_list_name: self.model_list_value,
                            self.num_sample_name: self.num_sample_value,
                            self.batch_parameter_name: self.batch_parameter_dict}}
